// Base64-embedded copies of bookings-icon-studios's public/logo-light.png
// and public/logo-dark.png — fixed 'Powered by IconStudios' platform
// branding, confirmed NOT touched by scripts/theme-setup.js and not part
// of any theme's swappable assets (the similarly-named files under
// themes/*/images/ are a different thing entirely — each shop's own logo).
// Embedded as data URIs rather than referenced by path, since a plain
// string path into node_modules isn't servable by the consuming app's
// Next.js the way a real /public asset is.

export const LOGO_LIGHT = "data:image/png;base64,";

export const LOGO_DARK = "data:image/png;base64,";
